insert into public.catalog_releases (release_id, country_code, version, status, data_checked_until, notes, source_notes, road_factor, avg_kmh, road_calibrated, road_note, airport_radius_km, previous_release_id) values
  ('GR-2', 'GR', 2, 'bozza', '2026-11-20', 'Catalogo ampliato: città, musei, parchi, natura, aeroporti, stazioni e aree portuali. Coordinate Wikidata e foto Commons con attribuzione. La presenza di un punto di trasporto non conferma servizi attivi, tratte, orari o prezzi. Coordinate portuali riferite all’area, non al molo di imbarco. Ampliamento additivo nel range 300–400: identità, coordinate e categorie da Wikidata; informazioni operative da verificare.', '[{"label":"Wikidata: dati strutturati CC0","url":"https://www.wikidata.org/wiki/Wikidata:Licensing","checkedAt":"2026-11-19","license":"CC0-1.0"},{"label":"Ente turistico · Grecia","url":"https://www.visitgreece.gr/","checkedAt":"2026-11-19","note":"Consultato per il contesto e la copertura; testi e immagini non importati"},{"label":"Ampliamento catalogo · ricerca strutturata Wikidata","url":"https://www.wikidata.org/wiki/Wikidata:Licensing","checkedAt":"2026-11-20","license":"CC0-1.0","note":"Dati strutturati; nessun testo enciclopedico importato. Zone non attribuibili mantenute nell’area nazionale, senza dedurre confini dalla vicinanza."}]'::jsonb, null, null, false, 'Parametri stradali non calibrati per questa nazione. I tempi del configuratore sono indicativi: calcolare i trasferimenti prima di attivare.', null, 'GR-1')
